-- Streamly practice database for the course "SQL for Everyone".
CREATE TABLE plans (plan_id int PRIMARY KEY, name text NOT NULL, monthly_price numeric(6,2) NOT NULL);
CREATE TABLE users (user_id int PRIMARY KEY, email text, country text NOT NULL, signup_date date NOT NULL, channel text NOT NULL);
CREATE TABLE visits (visit_id int PRIMARY KEY, visited_at timestamp NOT NULL, channel text NOT NULL, user_id int REFERENCES users(user_id));
CREATE TABLE subscriptions (subscription_id int PRIMARY KEY, user_id int NOT NULL REFERENCES users(user_id), plan_id int NOT NULL REFERENCES plans(plan_id), start_date date NOT NULL, end_date date);
CREATE TABLE payments (payment_id int PRIMARY KEY, subscription_id int NOT NULL REFERENCES subscriptions(subscription_id), paid_at timestamp NOT NULL, amount numeric(8,2), status text NOT NULL);
CREATE TABLE titles (title_id int PRIMARY KEY, title text NOT NULL, genre text NOT NULL, release_year int NOT NULL);
CREATE TABLE events (event_id int PRIMARY KEY, user_id int NOT NULL REFERENCES users(user_id), event_type text NOT NULL, title_id int REFERENCES titles(title_id), occurred_at timestamp NOT NULL);
CREATE TABLE support_tickets (ticket_id int PRIMARY KEY, user_id int NOT NULL REFERENCES users(user_id), opened_at timestamp NOT NULL, closed_at timestamp, category text NOT NULL);
CREATE TABLE contacts_raw (contact_id int PRIMARY KEY, full_name text, email text, phone text, country text, signup_date text, plan text, notes text);










ANALYZE;
